//! TLS configuration for the QUIC connection (mirrors `setupQUICConnection`
//! in the Go CLI).
//!
//! The trust roots are the system roots plus, optionally, the certificates
//! pinned in a known_hosts file for the host being connected to. When the
//! pinned certificates do not match the host name (typically self-signed
//! certificates generated by `sshoq-server -generate-selfsigned-cert`, which
//! carry the `selfsigned.ssh3` DNS SAN), verification is retried against that
//! name — the pinned certificate is its own trust anchor.

use std::path::PathBuf;
use std::sync::Arc;

use rustls::client::WebPkiServerVerifier;
use rustls::client::danger::{HandshakeSignatureValid, ServerCertVerified, ServerCertVerifier};
use rustls::pki_types::{CertificateDer, DnsName, ServerName, UnixTime};
use rustls::{DigitallySignedStruct, Error as TlsError, RootCertStore, SignatureScheme};

use crate::error::{Error, Result};
use crate::known_hosts::KnownHosts;

/// The DNS name carried by self-signed certificates generated by
/// `sshoq-server -generate-selfsigned-cert`.
pub const SELFSIGNED_SSH3_DNS_NAME: &str = "selfsigned.ssh3";

/// TLS (and QUIC transport) configuration for connecting to a server.
#[derive(Debug, Clone, Default)]
pub struct ClientTlsConfig {
    /// A known_hosts file whose pinned certificates are trusted for the host
    /// being connected to.
    known_hosts_file: Option<PathBuf>,
    /// Disable certificate verification entirely (like `sshoq -insecure`).
    insecure: bool,
    /// Additional root certificates to trust (e.g. a private CA).
    additional_roots: Vec<CertificateDer<'static>>,
}

impl ClientTlsConfig {
    /// A configuration trusting the system root certificates.
    pub fn with_system_roots() -> Self {
        ClientTlsConfig::default()
    }

    /// A configuration that does not verify the server certificate at all.
    ///
    /// This is dangerous: it accepts any certificate, including
    /// machine-in-the-middle attacks. It mirrors the `-insecure` flag of the
    /// Go CLI.
    pub fn insecure() -> Self {
        ClientTlsConfig {
            insecure: true,
            ..ClientTlsConfig::default()
        }
    }

    /// Trust the certificates pinned in this known_hosts file for the host
    /// being connected to (on top of the system roots).
    pub fn with_known_hosts_file(mut self, path: impl Into<PathBuf>) -> Self {
        self.known_hosts_file = Some(path.into());
        self
    }

    /// Trust an additional root certificate (DER-encoded).
    pub fn with_root_certificate(mut self, der: CertificateDer<'static>) -> Self {
        self.additional_roots.push(der);
        self
    }

    /// Trust additional root certificates (DER-encoded).
    pub fn with_root_certificates(mut self, ders: Vec<CertificateDer<'static>>) -> Self {
        self.additional_roots.extend(ders);
        self
    }

    /// Whether certificate verification is disabled.
    pub fn is_insecure(&self) -> bool {
        self.insecure
    }

    /// Build the rustls client configuration for connecting to
    /// `canonical_host` (the [`Config::canonical_host_format`] string, used to
    /// look up known_hosts pins).
    pub(crate) fn build_rustls_config(&self, canonical_host: &str) -> Result<rustls::ClientConfig> {
        let mut roots = RootCertStore::empty();

        // known_hosts pins for this host are trusted directly: a pinned
        // certificate is its own anchor, which is what makes self-signed
        // server certificates work without a CA.
        let mut pinned: Vec<CertificateDer<'static>> = Vec::new();
        if let Some(path) = &self.known_hosts_file {
            let known_hosts = KnownHosts::parse_file(path)?;
            if let Some(certs) = known_hosts.certificates(canonical_host) {
                pinned = certs.to_vec();
            }
        }

        for cert in &pinned {
            roots.add(cert.clone())?;
        }

        let result = rustls_native_certs::load_native_certs();
        let (added, ignored) = roots.add_parsable_certificates(result.certs);
        if added == 0 && pinned.is_empty() && self.additional_roots.is_empty() {
            return Err(Error::Tls(TlsError::General(format!(
                "no usable system root certificates ({ignored} ignored, {} load errors)",
                result.errors.len()
            ))));
        }
        for cert in &self.additional_roots {
            roots.add(cert.clone())?;
        }

        let verifier: Arc<dyn ServerCertVerifier> = if self.insecure {
            Arc::new(InsecureServerCertVerifier::new())
        } else {
            let inner = WebPkiServerVerifier::builder(Arc::new(roots))
                .build()
                .map_err(|e| {
                    Error::Tls(TlsError::General(format!(
                        "could not build the TLS verifier: {e}"
                    )))
                })?;
            Arc::new(Ssh3ServerCertVerifier {
                inner,
                retry_with_selfsigned_ssh3: !pinned.is_empty(),
            })
        };

        let mut config = rustls::ClientConfig::builder()
            .dangerous()
            .with_custom_certificate_verifier(verifier)
            .with_no_client_auth();
        // QUIC requires ALPN; SSHOQ speaks HTTP/3.
        config.alpn_protocols = vec![b"h3".to_vec()];
        Ok(config)
    }
}

/// A certificate verifier for SSHOQ: standard webpki verification against the
/// system roots plus the known_hosts pins, with a fallback to the
/// `selfsigned.ssh3` DNS name used by self-signed sshoq server certificates
/// (mirrors the Go client, which switches `tlsConf.ServerName` to
/// `selfsigned.ssh3` when a known-hosts certificate carries that SAN).
#[derive(Debug)]
struct Ssh3ServerCertVerifier {
    inner: Arc<WebPkiServerVerifier>,
    retry_with_selfsigned_ssh3: bool,
}

impl ServerCertVerifier for Ssh3ServerCertVerifier {
    fn verify_server_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        intermediates: &[CertificateDer<'_>],
        server_name: &ServerName<'_>,
        ocsp_response: &[u8],
        now: UnixTime,
    ) -> std::result::Result<ServerCertVerified, TlsError> {
        match self.inner.verify_server_cert(
            end_entity,
            intermediates,
            server_name,
            ocsp_response,
            now,
        ) {
            Ok(verified) => Ok(verified),
            Err(err) => {
                if !self.retry_with_selfsigned_ssh3 {
                    return Err(err);
                }
                // The pinned certificate may be a self-signed one carrying the
                // selfsigned.ssh3 SAN but no SAN matching the host name we
                // dialed (often an IP address): verify it against that name,
                // as the Go client does.
                let name: ServerName<'static> = ServerName::DnsName(
                    DnsName::try_from(SELFSIGNED_SSH3_DNS_NAME)
                        .expect("selfsigned.ssh3 is a valid DNS name")
                        .to_owned(),
                );
                self.inner
                    .verify_server_cert(end_entity, intermediates, &name, ocsp_response, now)
            }
        }
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, TlsError> {
        self.inner.verify_tls12_signature(message, cert, dss)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, TlsError> {
        self.inner.verify_tls13_signature(message, cert, dss)
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.inner.supported_verify_schemes()
    }
}

/// A certificate verifier that accepts any certificate (the `-insecure`
/// mode). TLS handshake signatures are still verified against the
/// certificate's public key, so the connection is still encrypted and
/// authenticated at the TLS-signature level, but the certificate chain and
/// identity are not checked.
#[derive(Debug)]
struct InsecureServerCertVerifier {
    supported_algs: rustls::crypto::WebPkiSupportedAlgorithms,
}

impl InsecureServerCertVerifier {
    fn new() -> Self {
        InsecureServerCertVerifier {
            supported_algs: rustls::crypto::ring::default_provider()
                .signature_verification_algorithms,
        }
    }
}

impl ServerCertVerifier for InsecureServerCertVerifier {
    fn verify_server_cert(
        &self,
        _end_entity: &CertificateDer<'_>,
        _intermediates: &[CertificateDer<'_>],
        _server_name: &ServerName<'_>,
        _ocsp_response: &[u8],
        _now: UnixTime,
    ) -> std::result::Result<ServerCertVerified, TlsError> {
        Ok(ServerCertVerified::assertion())
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, TlsError> {
        rustls::crypto::verify_tls12_signature(message, cert, dss, &self.supported_algs)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, TlsError> {
        rustls::crypto::verify_tls13_signature(message, cert, dss, &self.supported_algs)
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.supported_algs.supported_schemes()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builds_with_system_roots() {
        let config = ClientTlsConfig::with_system_roots()
            .build_rustls_config("example.org:443/sshoq-server")
            .unwrap();
        assert_eq!(config.alpn_protocols, vec![b"h3".to_vec()]);
    }

    #[test]
    fn builds_insecure() {
        let config = ClientTlsConfig::insecure()
            .build_rustls_config("example.org:443/sshoq-server")
            .unwrap();
        assert_eq!(config.alpn_protocols, vec![b"h3".to_vec()]);
    }

    #[test]
    fn builds_with_known_hosts_pins() {
        // a known_hosts file with a pin for the host: the pin is trusted even
        // though it is not a system root
        let dir = tempfile::tempdir().unwrap();
        let kh_path = dir.path().join("known_hosts");
        // generate a self-signed certificate with openssl in the e2e test; here
        // just check the plumbing with an empty pin set (missing file -> no pins)
        let config = ClientTlsConfig::with_system_roots()
            .with_known_hosts_file(&kh_path)
            .build_rustls_config("example.org:443/sshoq-server")
            .unwrap();
        assert_eq!(config.alpn_protocols, vec![b"h3".to_vec()]);
    }
}
